SELECT x.path, x.body,
  json_patch(json_patch('{}', json_object('path', x.path, 'state', x.state, 'cause', x.cause, 'why', x.why, 'fault', x.fault, 'enabled', CASE WHEN coalesce(x.on_fix, x.on_test, x.on_why, coalesce(x.was_cause, x.was_fault, x.was_why, x.was_since, (SELECT 1 FROM reuse_evidence c WHERE c.path = x.path AND c.kind = 'was' LIMIT 1)), x.on_epoch) IS NOT NULL THEN json_object('fix', x.on_fix, 'test', x.on_test, 'why', x.on_why, 'was', CASE WHEN coalesce(x.was_cause, x.was_fault, x.was_why, x.was_since, (SELECT 1 FROM reuse_evidence c WHERE c.path = x.path AND c.kind = 'was' LIMIT 1)) IS NOT NULL THEN json_object('cause', x.was_cause, 'fault', x.was_fault, 'why', x.was_why, 'since', x.was_since, 'evidence', json(nullif(nullif((SELECT json_patch('{}', json_object('path', c.path, 'key', c.key, 'fresh', c.fresh, 'reused', c.reused, 'fresh_from', c.fresh_from, 'epoch', c.epoch, 'repeated', CASE c.repeated WHEN 1 THEN json('true') WHEN 0 THEN json('false') END, 'again', nullif(json_patch('{}', json_object('fresh', c.again_fresh, 'reused', c.again_reused)), '{}'), 'fields', nullif(json_patch('{}', json_object('base', c.base, 'bin', c.bin, 'checker', c.checker, 'closure', c.closure, 'config', c.config, 'corpus', c.corpus, 'entry', c.entry, 'env', c.env, 'identity', c.identity, 'key', c.field_key, 'node', c.node, 'remote', c.remote, 'repo', c.repo, 'rust_identity', c.rust_identity, 'selection', c.selection, 'sha', c.sha, 'step', c.step, 'tools', c.tools, 'tree', c.tree)), '{}'))) FROM reuse_evidence c WHERE c.path = x.path AND c.kind = 'was'), '[]'), '{}'))) END, 'epoch', x.on_epoch) END, 'since', x.since, 'window', CASE WHEN coalesce(x.window_agreed, x.window_compared, x.window_disagreed, x.window_flakes, x.window_sampled, x.window_start, x.window_uses, x.window_unbacked) IS NOT NULL THEN json_object('agreed', x.window_agreed, 'compared', x.window_compared, 'disagreed', x.window_disagreed, 'flakes', x.window_flakes, 'sampled', x.window_sampled, 'start', x.window_start, 'uses', x.window_uses, 'unbacked', x.window_unbacked) END, 'closed', json(nullif(nullif((SELECT json_group_array(json_patch('{}', json_object('agreed', c.agreed, 'compared', c.compared, 'disagreed', c.disagreed, 'flakes', c.flakes, 'sampled', c.sampled, 'start', c.start, 'uses', c.uses, 'unbacked', c.unbacked)) ORDER BY c.ord) FROM reuse_windows c WHERE c.path = x.path), '[]'), '{}')), 'evidence', json(nullif(nullif((SELECT json_patch('{}', json_object('path', c.path, 'key', c.key, 'fresh', c.fresh, 'reused', c.reused, 'fresh_from', c.fresh_from, 'epoch', c.epoch, 'repeated', CASE c.repeated WHEN 1 THEN json('true') WHEN 0 THEN json('false') END, 'again', nullif(json_patch('{}', json_object('fresh', c.again_fresh, 'reused', c.again_reused)), '{}'), 'fields', nullif(json_patch('{}', json_object('base', c.base, 'bin', c.bin, 'checker', c.checker, 'closure', c.closure, 'config', c.config, 'corpus', c.corpus, 'entry', c.entry, 'env', c.env, 'identity', c.identity, 'key', c.field_key, 'node', c.node, 'remote', c.remote, 'repo', c.repo, 'rust_identity', c.rust_identity, 'selection', c.selection, 'sha', c.sha, 'step', c.step, 'tools', c.tools, 'tree', c.tree)), '{}'))) FROM reuse_evidence c WHERE c.path = x.path AND c.kind = 'now'), '[]'), '{}')))), coalesce(x.rest, '{}')) AS doc
FROM reuse_audit x
